+document.addEventListener('DOMContentLoaded', function() {
+    const form = document.getElementById('notificationForm');
+    const messageEl = document.getElementById('message');
+    const radios = document.querySelectorAll('input[name="notification-preference"]');
+
+    form.addEventListener('submit', function(e) {
+        e.preventDefault();
+        
+        const selectedValue = document.querySelector('input[name="notification-preference"]:checked');
+        
+        if (!selectedValue) {
+            showMessage('Please select a notification preference', 'error');
+            return;
+        }
+        
+        showMessage(`✓ Preferences saved! You selected: ${selectedValue.value.charAt(0).toUpperCase() + selectedValue.value.slice(1)}`, 'success');
